R=Path(__file__).resolve().parents[3];out=R/'downloads';out.mkdir(exist_ok=True)
ink=HexColor('#203d4a');teal=HexColor('#176c66');line=HexColor('#ccd8d2')
def base(c,title,sub,page):
 c.setFillColor(teal);c.rect(0,750,612,42,fill=1,stroke=0);c.setFillColor(HexColor('#ffffff'));c.setFont('Helvetica-Bold',12);c.drawString(42,766,'NEXALYPLANNER  /  FREE WORKSHEET')
 c.setFillColor(ink);c.setFont('Helvetica-Bold',23);c.drawString(42,705,title);c.setFont('Helvetica',10);c.drawString(42,682,sub)
 c.setFont('Helvetica',9);c.drawString(42,30,'nexalyplanner.com  |  US Letter  |  Static writing sheet, not a fillable form');c.drawRightString(570,30,str(page))
def cleaning():
 c=canvas.Canvas(str(out/'adhd-cleaning-planner.pdf'),pagesize=letter);c.setTitle('ADHD Cleaning Planner - Blank and Fictional Example');c.setAuthor('NexalyPlanner')
 for pg in [1,2]:
  base(c,'A small-step cleaning plan','Blank weekly sheet' if pg==1 else 'Fictional filled example - estimates, not actual time tracking',pg)
  c.setFont('Helvetica',11);c.drawString(42,646,'Week / label: '+('_______________________________' if pg==1 else 'Example week'))
  cols=[42,112,214,430,484,570];y=605
  c.setFillColor(teal);c.rect(42,y,528,28,fill=1,stroke=0);c.setFillColor(HexColor('#ffffff'));c.setFont('Helvetica-Bold',9)
  for x,t in zip(cols,['Day','Area','Small next action','Minutes','Status']):c.drawString(x+6,y+10,t)
  c.setFillColor(ink)
  rows=[['Monday','Office','Clear one desk corner','5','Done'],['Tuesday','Kitchen','Clear sink area','10','Planned'],['Friday','Bedroom','Fold one small basket','5','Skipped']] if pg==2 else []
  for i in range(7):
   yy=y-(i+1)*38;c.setStrokeColor(line);c.rect(42,yy,528,38,stroke=1,fill=0)
   for xx in cols[1:-1]:c.line(xx,yy,xx,yy+38)
   if i<len(rows):
    c.setFont('Helvetica',9)
    for x,t in zip(cols,rows[i]):c.drawString(x+6,yy+15,t)
  c.setFont('Helvetica-Bold',11);c.drawString(42,300,'Review without catching up on everything')
  c.setFont('Helvetica',10)
  review=['Estimated total: 20 min  |  Done: 5  |  Still planned: 10  |  Skipped: 5','Resume point: clear just the sink area when I choose to restart.','Skipped is a decision, not a debt to add to tomorrow.'] if pg==2 else ['Estimated total: ______  Done: ______  Still planned: ______  Skipped: ______','My next small restart point: __________________________________________','One thing to drop or simplify: _________________________________________']
  for i,t in enumerate(review):c.drawString(42,270-i*26,t)
  c.setFont('Helvetica',10)
  for i,t in enumerate(['Choose one visible action. Add an estimate, not a deadline for being perfect.','Use planned, done or skipped. Adjust the plan when the day changes.','This is an organizational worksheet, not medical guidance or ADHD treatment.','For editable entries and JSON backup, open the free online cleaning planner.']):c.drawString(42,150-i*18,t)
  c.showPage()
 c.save()
def cover():
 c=canvas.Canvas(str(out/'business-plan-cover-page.pdf'),pagesize=letter);c.setTitle('Business Plan Cover Page - Blank');c.setAuthor('NexalyPlanner');base(c,'Business plan cover page','Blank layout - enter your document details before sharing',1)
 c.setStrokeColor(teal);c.setLineWidth(3);c.line(42,626,570,626)
 y=594
 for label in ['Company / trading name','Document title','Subtitle / planning period','Prepared by','Prepared for','Contact','Version','Fixed issue date (YYYY-MM-DD)','Classification / handling note']:
  c.setFillColor(ink);c.setFont('Helvetica-Bold',11);c.drawString(42,y,label);c.setStrokeColor(line);c.setLineWidth(1);c.line(42,y-24,570,y-24);y-=53
 c.setFont('Helvetica',9);c.drawString(42,70,'A cover page does not supply the plan content, verify facts or create legal confidentiality.');c.save()
cleaning();cover()
